    wire logic signed [6:0] x1_3 = {{3{q0_11[3]}}, q0_11};
    wire logic signed [6:0] x1_4 = {{3{q0_12[3]}}, q0_12};
    wire logic signed [6:0] x1_5 = {{3{q0_13[3]}}, q0_13};
    wire logic signed [6:0] x1_6 = {{3{q0_14[3]}}, q0_14};
    wire logic signed [6:0] x1_7 = {{3{q0_15[3]}}, q0_15};
    wire logic signed [6:0] s1 = x1_0 + x1_1 + x1_2 + x1_3 + x1_4 + x1_5 + x1_6 + x1_7;
    wire logic signed [6:0] x2_0 = {{3{q0_16[3]}}, q0_16};
    wire logic signed [6:0] x2_1 = {{3{q0_17[3]}}, q0_17};
    wire logic signed [6:0] x2_2 = {{3{q0_18[3]}}, q0_18};
    wire logic signed [6:0] x2_3 = {{3{q0_19[3]}}, q0_19};
    wire logic signed [6:0] x2_4 = {{3{q0_20[3]}}, q0_20};
    wire logic signed [6:0] x2_5 = {{3{q0_21[3]}}, q0_21};
    wire logic signed [6:0] x2_6 = {{3{q0_22[3]}}, q0_22};
    wire logic signed [6:0] x2_7 = {{3{q0_23[3]}}, q0_23};
    wire logic signed [6:0] s2 = x2_0 + x2_1 + x2_2 + x2_3 + x2_4 + x2_5 + x2_6 + x2_7;
    wire logic       ge10 = s1 > s0;
    wire logic signed [6:0] m01 = ge10 ? s1 : s0;
    wire logic [1:0] c01 = ge10 ? 2'd1 : 2'd0;
    wire logic [1:0] cls = (s2 > m01) ? 2'd2 : c01;
    logic [LATENCY-1:0] vpipe;
    always_ff @(posedge clk) begin
        out_cls <= cls;
        if (rst) vpipe <= '0; else vpipe <= {vpipe[LATENCY-2:0], in_v};
    end
    assign out_v = vpipe[LATENCY-1];
endmodule
`default_nettype wire
